describe('Modal with Tabbed Content - Tab Persistence', () => {
  beforeEach(() => {
    cy.visit('/modal-tabs');
  });

  it('should remember the active tab when modal is closed and reopened', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Click on the first tab
    cy.get('[data-testid="tab-1-button"]').click();
    cy.get('[data-testid="tab-1-content"]').should('be.visible');
    cy.get('[data-testid="tab-1-button"]').should('have.class', 'active');

    // Close the modal
    cy.get('[data-testid="close-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('not.exist');

    // Reopen the modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Verify the first tab is still active
    cy.get('[data-testid="tab-1-button"]').should('have.class', 'active');
    cy.get('[data-testid="tab-1-content"]').should('be.visible');

    // Verify other tabs are not active
    cy.get('[data-testid="tab-2-button"]').should('not.have.class', 'active');
    cy.get('[data-testid="tab-3-button"]').should('not.have.class', 'active');
  });

  it('should remember the active tab when navigating between tabs and closing modal', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Click on the second tab
    cy.get('[data-testid="tab-2-button"]').click();
    cy.get('[data-testid="tab-2-content"]').should('be.visible');
    cy.get('[data-testid="tab-2-button"]').should('have.class', 'active');

    // Click on the third tab
    cy.get('[data-testid="tab-3-button"]').click();
    cy.get('[data-testid="tab-3-content"]').should('be.visible');
    cy.get('[data-testid="tab-3-button"]').should('have.class', 'active');

    // Close the modal
    cy.get('[data-testid="close-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('not.exist');

    // Reopen the modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Verify the third tab is still active
    cy.get('[data-testid="tab-3-button"]').should('have.class', 'active');
    cy.get('[data-testid="tab-3-content"]').should('be.visible');

    // Verify other tabs are not active
    cy.get('[data-testid="tab-1-button"]').should('not.have.class', 'active');
    cy.get('[data-testid="tab-2-button"]').should('not.have.class', 'active');
  });
});
